import React from 'react';
import './Todolist.css';

//komponen Todo
function Todo(props) {
  return (
    <div className="containerList m-auto d-flex border border-1 border-light text-light bg-secondary" >
      <div className="ps-3">
        {props.text}
      </div>
      <div className='cross text-center del ms-auto' id={props.id} onClick={props.onDelete} >
        x
      </div>
    </div>
  )
}

//komponen TodoList
function TodoList() {

  var tanggal = new Date();

    const todos = [{ id: 1, text: 'Belajar HTML' }];
  
    const [inputTodo, setInputTodo] = React.useState('');
    const [error, setError] = React.useState(null);
    const [arrayTodo, setArrayTodo] = React.useState(todos);
  
  
    const handleTodoChange = (e) => {
      setInputTodo(e.target.value);
    }
  
    const handleAddTodo = (text) => {
      const newTodos = [...arrayTodo, { id: new Date().getTime().toString(), text: text }];
      setArrayTodo(newTodos);
    }
  
    const handleSubmit = (e) => {
      e.preventDefault();
      if (inputTodo.trim() === '') {
        setError('Kolom tidak terisi...!');
      }
      else {
        handleAddTodo(inputTodo);
        setInputTodo('');
        setError('');
      }
    }
  
    const handleDeleteClick = (e) => {
      const newTodos = arrayTodo.filter((list) => {
        return list.id !== e.target.id;
      }
      );
      setArrayTodo(newTodos);
    }
  
    const handleTodoFocus = (e) => {
      e.target.style.outlineStyle = 'none';
    }
  
    return (
      <div class="todolistbase px-0 container border-start border-end border-bottom border-4 pt-5 px-0">
      
          {
            arrayTodo.map((todo) => {
              return <Todo key={todo.id} id={todo.id} text={todo.text} onDelete={handleDeleteClick} />
            }
            )
          }
          
            <form class="frm m-auto" onSubmit={handleSubmit}>
              <input id='text' type='text' name='inputTodo' value={inputTodo} size='53' autoComplete='off' className="border border-1 text-secondary" onFocus={handleTodoFocus} onChange={handleTodoChange} />
              <input type='submit' name='add' value='add' className="border border-1 text-secondary" />
            </form>
            <p className="pesan px-0 text-danger" >{error && <small>{error}</small>} </p>
          
        
      <div className='footer mt-5 d-flex flex-column align-items-center py-3'>
            <a className='text-decoration-none text-light mb-2' href='josuasiregar47@gmail.com'>josuasiregar47@gmail.com
            </a>

              <span className='bi-instagram text-white'>
                <a href="https://instagram.com/id.jees?igshd=ZDdkNTZiNTM" target="_blank" className="text-white text-decoration-none p-1">
                  id.jees
                  </a>
              </span>

          <p className='mb-0 mt-4 text-light'>
            Copyright &copy; {tanggal.getFullYear()} Josua Siregar
          </p>
          </div>
      </div>
      
    )
  }


export default TodoList;
