import React from 'react';
import './Navbar.css';
import { Link } from 'react-router-dom';

function Navbar() {
  return (
    <div className='base container border-start border-end border-1 border-top border-4 px-0'>
      <div className='navbar navbar-expand'>
        <div className='container-fluid'>
          <ul className='navbar-nav'>
            <li>
              <Link className='nav-item nav-link' to='/'>Beranda</Link>
            </li>
            <li>
              <Link className='nav-item nav-link' to='/tentang'>Tentang</Link>
            </li>
            <li>
              <span className='nav-item nav-link'>Project</span>
            </li>
            
            <li className='dropdown'>
              <button className='border-0 nav-item nav-link dropdown-toggle dropdown-toggle-split' data-bs-toggle="dropdown">
                <span className='visually-hidden'>navbar-dropdown</span>
              </button>
              <div className='dropdown-menu'>
                <Link className='dropdown-item' to='/kalkulator'>
                  Kalkulator
                </Link>
                <Link className='dropdown-item' to='/todolist'>
                  TodoList
                </Link>
                <a href="http://jeescode.rf.gd/" target="_blank" className="dropdown-item text-decoration-none text-dark">
                  CRUD
                </a>
              </div>
            </li>
          </ul>
        </div>
      </div>
    </div>
  )
}

export default Navbar;
